class Widget {
    private final EventBus bus;
    private final byte[] icon = new byte[5_000_000];

    Widget(EventBus bus) {
        this.bus = bus;                          // the bus lives for the whole app
        bus.subscribe(event -> repaint(event));  // uses an instance method
    }

    void close() {
        // the application drops its own reference to this Widget here
    }
}
